    .reg .f16  %val;
    .reg .f16  %zero;
    .reg .pred %p;

    // Load kernel parameters
    ld.param.u64 %input_ptr, [__cudaparm_relu_fp16_input];
    ld.param.u64 %output_ptr, [__cudaparm_relu_fp16_output];
    ld.param.u64 %N, [__cudaparm_relu_fp16_N];

    // Compute thread index
    mov.u32 %tid.x, %tid.x;
    mov.u32 %blkId.x, %ctaid.x;
    mov.u32 %blkDim.x, %ntid.x;
    mul.wide.u32 %global_idx, %blkId.x, %blkDim.x;
    add.u64 %global_idx, %global_idx, %tid.x;

    // Compute stride = gridDim.x * blockDim.x
    mov.u64 %gridDim.x, %nctaid.x;
    cvt.u64.u32 %stride, %blkDim.x;
    mul.lo.u64 %stride, %stride, %gridDim.x;

    // Initialize zero constant (half precision zero)
    mov.f16 %zero, 0f0000;

BB_LOOP:
    // while (global_idx < N)
    setp.ge.u64 %p, %global_idx, %N;
    @%p bra BB_EXIT;

    // Load input value
    ld.global.f16 %val, [%input_ptr + %global_idx*2]; // each fp16 = 2 bytes

    // ReLU: max(val, 0)
    max.f16 %val, %val, %zero;

    // Store result
    st.global.f16 [%output_ptr + %global_idx*2], %val;

    // global_idx += stride
    add.u64 %global_idx, %global_idx, %stride;
    bra BB_LOOP;

BB_EXIT:
    ret;
}
'''
